import{_ as e,o as l,c as d,a2 as a}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"即时解答与关键词扩展功能","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/instant-answers.md","filePath":"zh-CN/user-guide/instant-answers.md","lastUpdated":1788190459000}'),o={name:"zh-CN/user-guide/instant-answers.md"};function s(n,t,i,r,c,g){return l(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="即时解答与关键词扩展功能" tabindex="-1">即时解答与关键词扩展功能 <a class="header-anchor" href="#即时解答与关键词扩展功能" aria-label="Permalink to &quot;即时解答与关键词扩展功能&quot;">​</a></h1><p>除了本地文件检索之外，Lertaro 还内置了一系列强大的即时计算、系统工具与关键词扩展插件。无需等待文件检索，输入对应指令即可即刻得到答案或触发专业功能。</p><h2 id="_1-始终生效的即时解答" tabindex="-1">1. 始终生效的即时解答 <a class="header-anchor" href="#_1-始终生效的即时解答" aria-label="Permalink to &quot;1. 始终生效的即时解答&quot;">​</a></h2><p>无需输入任何前缀关键词，只要输入的文本匹配特定模式即可立即触发：</p><h3 id="计算器与进制转换" tabindex="-1">计算器与进制转换 <a class="header-anchor" href="#计算器与进制转换" aria-label="Permalink to &quot;计算器与进制转换&quot;">​</a></h3><p>直接在搜索框中输入数学表达式，计算结果将在第一行实时呈现。按下 <code>Enter</code> 键即可将计算结果复制到剪贴板：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span>
<span class="line"><span>100 * (1 - 0.15)</span></span></code></pre></div><p>支持常见的进制转换表达：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span>
<span class="line"><span>101010 to bin</span></span></code></pre></div><h3 id="环境变量展开与查询" tabindex="-1">环境变量展开与查询 <a class="header-anchor" href="#环境变量展开与查询" aria-label="Permalink to &quot;环境变量展开与查询&quot;">​</a></h3><ul><li><strong>精准展开变量</strong>：输入 <code>%NAME%</code>（如 <code>%PATH%</code>、<code>%APPDATA%</code>）可直接查看变量值。对于包含多个路径的变量（如 <code>PATH</code>），Lertaro 会自动将其拆分为清晰的逐行列表，便于检查环境配置。</li><li><strong>模糊搜索变量</strong>：输入 <code>%</code> 加上关键词（如 <code>%temp</code>）可模糊搜索所有名称中包含该关键词的系统与用户环境变量。</li></ul><h3 id="快捷运行命令" tabindex="-1">快捷运行命令 <a class="header-anchor" href="#快捷运行命令" aria-label="Permalink to &quot;快捷运行命令&quot;">​</a></h3><p>无需先打开终端窗口，直接在搜索框中输入：</p><ul><li><code>#&lt;命令&gt;</code>：打开命令行窗口并<strong>以管理员权限</strong>执行该命令（例如 <code>#sfc /scannow</code> 或 <code>#net start Lertaro.Service</code>）。</li><li><code>$&lt;命令&gt;</code>：打开命令行窗口以<strong>当前普通用户权限</strong>执行该命令（例如 <code>$ping 1.1.1.1</code> 或 <code>$ipconfig /all</code>）。</li></ul><h3 id="网址直达" tabindex="-1">网址直达 <a class="header-anchor" href="#网址直达" aria-label="Permalink to &quot;网址直达&quot;">​</a></h3><p>直接输入或粘贴以 <code>http://</code> 或 <code>https://</code> 开头的完整网址，按下 <code>Enter</code> 即可立即在默认浏览器中打开该页面。当输入没有搜索结果且以裸域名开头时，快速搜索窗口会自动填充 <code>https://</code> 并将光标移动到文本末尾；已经包含协议的输入不会被修改。</p><h3 id="快速搜索窗口导入剪贴板文本" tabindex="-1">快速搜索窗口导入剪贴板文本 <a class="header-anchor" href="#快速搜索窗口导入剪贴板文本" aria-label="Permalink to &quot;快速搜索窗口导入剪贴板文本&quot;">​</a></h3><p>快速搜索窗口在没有预填内容的情况下被呼出时，如果剪贴板文本不为空且不同于该窗口上一次导入的剪贴板内容，就会自动填入并全选文本。相同内容不会重复导入，从 URI 或完整搜索窗口返回时的预填内容也不会被覆盖。</p><h2 id="_2-关键词触发功能-内置插件" tabindex="-1">2. 关键词触发功能（内置插件） <a class="header-anchor" href="#_2-关键词触发功能-内置插件" aria-label="Permalink to &quot;2. 关键词触发功能（内置插件）&quot;">​</a></h2><p>通过输入简短的<strong>触发关键词 + 空格</strong>，再输入实际查询内容，即可调用专项插件能力。各关键词均可在<a href="./settings/plugins.html"><strong>设置 → 插件</strong></a>中自定义修改。</p><table tabindex="0"><thead><tr><th style="text-align:left;">默认关键词</th><th style="text-align:left;">插件名称</th><th style="text-align:left;">功能说明与使用场景</th><th style="text-align:left;">典型使用示例</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ps</code></td><td style="text-align:left;"><strong>进程管理</strong></td><td style="text-align:left;">按进程名、PID 或窗口标题搜索运行中的进程（支持拼音），回车一键结束进程。</td><td style="text-align:left;"><code>ps chrome</code> 或 <code>ps 1234</code></td></tr><tr><td style="text-align:left;"><code>win</code></td><td style="text-align:left;"><strong>窗口切换器</strong></td><td style="text-align:left;">搜索并即时切换到当前打开的应用窗口，支持后台实时抓取窗口缩略图。</td><td style="text-align:left;"><code>win code</code> 或 <code>win 微信</code></td></tr><tr><td style="text-align:left;"><code>bm</code></td><td style="text-align:left;"><strong>浏览器数据</strong></td><td style="text-align:left;">搜索 Chrome、Edge、Firefox 等浏览器的书签与历史访问记录（书签与历史可独立开关）。</td><td style="text-align:left;"><code>bm github</code></td></tr><tr><td style="text-align:left;"><code>set</code></td><td style="text-align:left;"><strong>设置搜索</strong></td><td style="text-align:left;">模糊搜索 Lertaro 自身的所有设置选项，选中即可直接跳转到对应设置页并高亮该项。</td><td style="text-align:left;"><code>set 热键</code> 或 <code>set 模糊</code></td></tr><tr><td style="text-align:left;"><code>flow</code></td><td style="text-align:left;"><strong>Flow 插件桥接</strong></td><td style="text-align:left;">列出所有已加载的 Flow.Launcher 插件及其触发词，支持无缝调用 Flow 社区生态。</td><td style="text-align:left;"><code>flow</code></td></tr><tr><td style="text-align:left;"><code>cs</code></td><td style="text-align:left;"><strong>内容搜索</strong></td><td style="text-align:left;">搜索已建立索引的本地文档正文，并返回带片段的匹配文件。</td><td style="text-align:left;"><code>cs 项目计划</code></td></tr></tbody></table><h2 id="_3-网页搜索快捷引擎" tabindex="-1">3. 网页搜索快捷引擎 <a class="header-anchor" href="#_3-网页搜索快捷引擎" aria-label="Permalink to &quot;3. 网页搜索快捷引擎&quot;">​</a></h2><p>网页搜索插件内置了主流搜索引擎快捷方式，输入对应前缀并跟随关键词即可一键拉起浏览器搜索：</p><table tabindex="0"><thead><tr><th style="text-align:left;">快捷词</th><th style="text-align:left;">对应搜索引擎</th><th style="text-align:left;">示例</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>bd</code></td><td style="text-align:left;">百度 (Baidu)</td><td style="text-align:left;"><code>bd 深度学习</code></td><td style="text-align:left;">在百度中搜索关键词</td></tr><tr><td style="text-align:left;"><code>g</code></td><td style="text-align:left;">谷歌 (Google)</td><td style="text-align:left;"><code>g lertaro github</code></td><td style="text-align:left;">在 Google 中搜索关键词</td></tr><tr><td style="text-align:left;"><code>bing</code></td><td style="text-align:left;">必应 (Bing)</td><td style="text-align:left;"><code>bing 微软文档</code></td><td style="text-align:left;">在 Bing 中搜索关键词</td></tr><tr><td style="text-align:left;"><code>gh</code></td><td style="text-align:left;">GitHub</td><td style="text-align:left;"><code>gh Lertaro</code></td><td style="text-align:left;">直接在 GitHub 仓库中搜索</td></tr><tr><td style="text-align:left;"><code>wiki</code></td><td style="text-align:left;">维基百科 (Wikipedia)</td><td style="text-align:left;"><code>wiki 量子力学</code></td><td style="text-align:left;">在维基百科中查阅词条</td></tr><tr><td style="text-align:left;"><code>yt</code></td><td style="text-align:left;">YouTube</td><td style="text-align:left;"><code>yt lofi hip hop</code></td><td style="text-align:left;">在 YouTube 中搜索视频</td></tr></tbody></table><p>你可以在<strong>设置 → 插件 → 网页搜索 → 配置</strong>中自由新增、修改或删除搜索引擎与自定义 URL 模板。</p><h2 id="_4-即时翻译" tabindex="-1">4. 即时翻译 <a class="header-anchor" href="#_4-即时翻译" aria-label="Permalink to &quot;4. 即时翻译&quot;">​</a></h2><p>输入默认触发词 <code>tr</code> 并在其后输入待翻译的内容，即可自动翻译为 Lertaro 当前所选的界面语言：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tr Hello, how are you today?</span></span></code></pre></div><ul><li>翻译结果随输入异步呈现，按 <code>Enter</code> 键即可一键复制译文。</li><li>可在<strong>设置 → 插件 → 翻译 → 配置</strong>中更改触发词或查看联网状态。</li></ul><h2 id="_5-文件过滤器" tabindex="-1">5. 文件过滤器 <a class="header-anchor" href="#_5-文件过滤器" aria-label="Permalink to &quot;5. 文件过滤器&quot;">​</a></h2><p>在<strong>设置 → 插件 → 文件过滤器 → 配置</strong>中，你可以为特定目录和扩展名建立专属过滤器规则：</p><ul><li><strong>指定监控目录</strong>：递归扫描指定工作目录（如 <code>D:\\Engineering\\Drawings</code>）。</li><li><strong>指定匹配规则</strong>：例如 <code>*.dwg;*.dxf</code> 或 <code>*.pdf;*.docx</code>（不影响子文件夹收录）。</li><li><strong>设置触发关键字</strong>：为该规则绑定专属前缀（如 <code>cad</code> 或 <code>doc</code>），输入 <code>cad 零件图</code> 即可实现特定业务资料的精准隔离搜索。</li></ul><h2 id="_6-自定义命令" tabindex="-1">6. 自定义命令 <a class="header-anchor" href="#_6-自定义命令" aria-label="Permalink to &quot;6. 自定义命令&quot;">​</a></h2><p>在<strong>设置 → 插件 → 自定义命令 → 配置</strong>中，你可以将任意复杂的命令行工具、脚本或外部应用包装为一个简短的启动命令：</p><ul><li><strong>参数占位符</strong>：支持位置占位符 <code>%s1</code>、<code>%s2</code>……（对应以空格分隔的参数）以及全文占位符 <code>%s</code>（代表关键词后的所有输入文本）。</li><li><strong>快速导航集成</strong>：勾选“在快速导航中显示”后，该命令会直接作为菜单项出现在<a href="./hotkeys.html#3-快速导航鼠标触发"><strong>快速导航</strong></a>中，支持使用 <code>/</code> 创建多级子菜单分类（如 <code>开发工具/重启服务</code>）。</li></ul>`,35)])])}const x=e(o,[["render",s]]);export{p as __pageData,x as default};
